class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        return "..."

    def intro(self):
        return f"{self.name} says {self.speak()}"

class Dog(Animal):
    def __init__(self, name, breed):
        super().__init__(name)   # sets self.name
        self.breed = breed

    def speak(self):             # overrides Animal.speak
        return "Woof"

d = Dog("Rex", "lab")
print(d.intro())              # Rex says Woof
print(isinstance(d, Animal))  # True

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __str__(self):
        return f"({self.x}, {self.y})"

    def __eq__(self, other):
        return self.x == other.x and self.y == other.y

p = Point(1, 2)
q = Point(1, 2)
print(p)          # (1, 2)
print(p == q)     # True, because of __eq__
print(p is q)     # False, still two objects

class Account:
    def __init__(self, owner):
        self.owner = owner
        self._balance = 0            # internal by convention

    def deposit(self, amount):
        if amount <= 0:
            raise ValueError("amount must be positive")
        self._balance += amount

    @property
    def balance(self):               # read as acct.balance
        return self._balance

class Engine:
    def start(self):
        return "engine on"

class Car:
    def __init__(self):
        self.engine = Engine()       # a Car has an Engine

    def start(self):
        return self.engine.start()

acct = Account("Ana")
acct.deposit(50)
print(acct.balance)    # 50
print(Car().start())   # engine on

